insert into meals (code, type, title, ingredients, portion_hint, instructions) values
  ('B1', 'breakfast', 'Овсянка с ягодами и йогуртом', ARRAY['овсяные хлопья', 'молоко или растительный напиток', 'ягоды (свежие или замороженные)', 'натуральный йогурт'], 'крупы — размер кулака, йогурт — половина ладони, ягод — сколько хочется', 'Сварите овсянку на молоке или воде 5–7 минут. Выложите в тарелку, добавьте ложку йогурта и ягоды сверху.'),
  ('B2', 'breakfast', '2 яйца, цельнозерновой хлеб и овощи', ARRAY['яйца', 'цельнозерновой хлеб', 'свежие овощи (огурец, помидор, зелень)'], 'белок — размер ладони (2 яйца), хлеб — 1–2 кусочка, овощей — 1–2 кулака', 'Отварите яйца или сделайте омлет. Нарежьте овощи. Подавайте с тостом из цельнозернового хлеба.'),
  ('B3', 'breakfast', 'Творог с ягодами и орехами', ARRAY['творог', 'ягоды', 'орехи (миндаль, грецкий)'], 'творог — размер ладони, орехов — небольшая горсть', 'Выложите творог в миску, добавьте ягоды и присыпьте измельчёнными орехами.'),
  ('B4', 'breakfast', 'Греческий йогурт с ягодами и овсянкой', ARRAY['греческий йогурт', 'ягоды', 'овсяные хлопья или гранола без сахара'], 'йогурт — размер ладони, овсянки — 2–3 ст. ложки', 'Смешайте йогурт с сухой овсянкой, дайте постоять 5 минут, добавьте ягоды перед подачей.'),
  ('B5', 'breakfast', 'Омлет с овощами и хлебом', ARRAY['яйца', 'овощи по вкусу (перец, шпинат, помидор)', 'цельнозерновой хлеб'], 'яиц — 2 шт., овощей — 1 кулак, хлеб — 1 кусочек', 'Взбейте яйца, добавьте нарезанные овощи, готовьте на среднем огне 4–5 минут под крышкой.'),
  ('L1', 'lunch', 'Курица с рисом и овощами', ARRAY['куриное филе или бедро', 'рис', 'сезонные овощи'], 'белок — ладонь, рис — кулак, овощи — 1–2 кулака', 'Отварите рис. Обжарьте или запеките курицу с приправами. Овощи потушите или подайте свежими.'),
  ('L2', 'lunch', 'Индейка с гречкой и овощами', ARRAY['филе индейки', 'гречка', 'овощи'], 'белок — ладонь, гречка — кулак, овощи — 1–2 кулака', 'Отварите гречку. Индейку обжарьте на сковороде или запеките. Подавайте с овощами.'),
  ('L3', 'lunch', 'Лосось с картофелем и салатом', ARRAY['филе лосося', 'картофель', 'листовой салат', 'оливковое масло'], 'рыба — ладонь, картофель — кулак, салата — 1–2 кулака', 'Запеките лосось в духовке 15 минут при 200°C. Отварите или запеките картофель. Заправьте салат маслом.'),
  ('L4', 'lunch', 'Говядина с булгуром и овощами', ARRAY['говядина (нежирная часть)', 'булгур', 'овощи'], 'белок — ладонь, булгур — кулак, овощи — 1–2 кулака', 'Отварите булгур. Говядину нарежьте и обжарьте до готовности. Подавайте с тушёными овощами.'),
  ('L5', 'lunch', 'Паста с курицей и овощами', ARRAY['паста из твёрдых сортов пшеницы', 'куриное филе', 'овощи', 'немного оливкового масла'], 'паста — кулак, курица — ладонь, овощи — 1 кулак', 'Отварите пасту. Курицу обжарьте кубиками, добавьте овощи, смешайте всё вместе.'),
  ('L6', 'lunch', 'Тунец с картофелем и салатом', ARRAY['тунец (консервированный в собственном соку или стейк)', 'картофель', 'листовой салат'], 'тунец — ладонь, картофель — кулак, салата — 1–2 кулака', 'Отварите картофель. Смешайте тунец с салатом, заправьте маслом и лимоном.'),
  ('L7', 'lunch', 'Чечевица с рисом и овощами', ARRAY['чечевица', 'рис', 'овощи'], 'чечевица — кулак, рис — половина кулака, овощи — 1–2 кулака', 'Отварите чечевицу и рис отдельно. Подавайте вместе со свежими или тушёными овощами.'),
  ('D1', 'dinner', 'Курица с овощами', ARRAY['куриное филе', 'овощи на выбор'], 'белок — ладонь, овощи — 1–2 кулака', 'Запеките или обжарьте курицу, подавайте с тушёными или свежими овощами.'),
  ('D2', 'dinner', 'Рыба с овощами и картофелем', ARRAY['белая рыба', 'овощи', 'картофель'], 'рыба — ладонь, картофель — половина кулака, овощи — 1–2 кулака', 'Запеките рыбу с лимоном 15–20 минут. Подавайте с отварным картофелем и овощами.'),
  ('D3', 'dinner', 'Индейка с салатом и крупой', ARRAY['филе индейки', 'листовой салат', 'крупа на выбор (небольшая порция)'], 'белок — ладонь, крупы — половина кулака, салата — 1–2 кулака', 'Обжарьте или отварите индейку, смешайте с салатом и небольшой порцией крупы.'),
  ('D4', 'dinner', 'Омлет с овощами и хлебом', ARRAY['яйца', 'овощи', 'цельнозерновой хлеб'], 'яиц — 2 шт., хлеб — 1 кусочек, овощей — 1 кулак', 'Приготовьте омлет с овощами, подавайте с ломтиком хлеба.'),
  ('D5', 'dinner', 'Творог с ягодами и орехами', ARRAY['творог', 'ягоды', 'орехи'], 'творог — ладонь, орехов — небольшая горсть', 'Смешайте творог с ягодами, добавьте немного орехов сверху.'),
  ('D6', 'dinner', 'Говядина с овощами', ARRAY['говядина (нежирная часть)', 'овощи'], 'белок — ладонь, овощи — 1–2 кулака', 'Обжарьте или запеките говядину, подавайте с большим количеством овощей.'),
  ('S1', 'snack', 'Яблоко с йогуртом', ARRAY['яблоко', 'натуральный йогурт'], '1 фрукт + половина ладони йогурта', 'Нарежьте яблоко, подавайте с йогуртом для перекуса.'),
  ('S2', 'snack', 'Банан с орехами', ARRAY['банан', 'орехи'], '1 фрукт + небольшая горсть орехов', 'Готовый перекус без приготовления — банан и горсть орехов.'),
  ('S3', 'snack', 'Творог с ягодами', ARRAY['творог', 'ягоды'], 'половина ладони творога + горсть ягод', 'Смешайте творог с ягодами.'),
  ('S4', 'snack', 'Йогурт с фруктом', ARRAY['натуральный йогурт', 'фрукт на выбор'], 'половина ладони йогурта + 1 фрукт', 'Нарежьте фрукт и смешайте с йогуртом.'),
  ('S5', 'snack', 'Фрукт с сыром', ARRAY['фрукт на выбор', 'лёгкий сыр'], '1 фрукт + 2–3 небольших кусочка сыра', 'Нарежьте фрукт и сыр, готово к перекусу.');
