insert into lessons (id, title, body) values
  ('no_perfect_diet', 'Почему не нужна идеальная диета', 'Идеальной диеты, которой можно придерживаться вечно без единого отклонения, не существует — и это нормально. Программы, которые обещают полный контроль над каждым приёмом пищи, обычно заканчиваются срывом, потому что жизнь не бывает предсказуемой: дни рождения, усталость, плохое настроение случаются у всех. BODY RESET построен иначе: не как список запретов, а как гибкая система «сбалансированная тарелка + движение + сон». Если один приём пищи вышел из плана — это не провал программы, а обычный день. Твоя задача не в том, чтобы ни разу не отклониться, а в том, чтобы после отклонения просто вернуться к следующему приёму пищи как обычно. Устойчивый результат строится не на идеальности, а на том, сколько дней подряд ты в целом действуешь в своих интересах. Раз в неделю неидеально — это не крах системы. Крах — это когда одно отклонение превращается в «ну и ладно, всё равно уже все испортила» на две недели. Именно этого мы и учимся избегать.'),
  ('weight_stalls', 'Почему вес может стоять на месте', 'Вес — не самый точный показатель прогресса день в день. Он колеблется из-за воды, соли, гормонального цикла, качества сна и даже количества клетчатки накануне — иногда на 1–2 кг за сутки, без всякой связи с жиром. Если весы несколько дней подряд показывают одно и то же, это не значит, что программа не работает. Гораздо честнее смотреть на динамику за 2–3 недели, а не на одно значение, и сверяться не только с весом, но и с объёмами, самочувствием, тем, как сидит одежда. Тело часто «застаивается» перед тем, как показать заметное изменение — это нормальная физиология, а не признак того, что ты делаешь что-то не так. Если ты выполняешь тренировки и в целом придерживаешься системы питания — продолжай. Резко урезать питание или добавлять экстра-тренировки в ответ на застой веса не нужно: это чаще приводит к откату, а не к ускорению результата. Дай телу время.'),
  ('after_overeating', 'Что делать после переедания', 'Один эпизод переедания не отменяет всю программу и не откатывает прогресс назад. Организму физически невозможно набрать заметный жир за один вечер — то, что ты чувствуешь на следующий день, это в основном вода и объём съеденного, а не жировая ткань. Самая частая ошибка — «компенсировать» переедание голоданием или экстремально урезанным следующим днём. Это только качает маятник «переел → поголодал → снова переел» и делает систему менее устойчивой, а не более. Правильный шаг простой и скучный: вернись к обычному следующему приёму пищи, как будто вчерашнего вечера не было. Не нужно его анализировать бесконечно, стыдить себя или устраивать разгрузочный день. Если это помогает — коротко отметь в приложении, что примерно этому предшествовало (стресс, недосып, слишком большой перерыв между приёмами пищи) — не чтобы себя судить, а чтобы в следующий раз было проще узнать похожую ситуацию заранее.'),
  ('sugar_cravings', 'Почему хочется сладкого', 'Тяга к сладкому редко бывает просто «слабостью характера» — чаще у неё есть конкретная причина. Самые частые: слишком большой перерыв между приёмами пищи, недостаток белка и клетчатки в рационе (из-за чего сахар в крови скачет), недосып, стресс или просто привычка «заедать» определённое время суток или эмоцию. Полный запрет сладкого обычно только усиливает желание — мозг воспринимает жёсткий запрет как дефицит и потом «наверстывает». Более рабочая стратегия — не убирать сладкое полностью, а: не приходить к вечеру сильно голодной (для этого и нужны сбалансированные приёмы пищи и перекусы в течение дня), добавлять белок и клетчатку к основным приёмам пищи, и, если хочется чего-то сладкого, — съесть это осознанно и с удовольствием, а не на бегу и не украдкой. Небольшая порция десерта в рамках в целом сбалансированного дня не откатывает прогресс. Стыд и запреты работают против тебя гораздо чаще, чем сам десерт.'),
  ('missed_workout', 'Что делать, если пропустила тренировку', 'Одна пропущенная тренировка ничего не решает в масштабе 56 дней — программа рассчитана так, чтобы выдерживать такие сбои. Единственное, что может реально навредить результату, — это решение «раз уж пропустила одну, значит, эта неделя уже не считается» и полный отказ от системы до понедельника. Если тренировка не случилась — не нужно пытаться «догнать» её вдвойне на следующий день или винить себя. Просто вернись к плану на сегодня так, как будто вчерашнего пропуска не было. Если пропуски повторяются несколько раз подряд, стоит честно посмотреть на причину: не хватает времени, слишком высокая нагрузка для текущего графика, или тренировки просто не приносят удовольствия. В этом случае лучше снизить частоту тренировок в настройках профиля до реалистичного числа, чем продолжать ставить недостижимую цель и каждый раз расстраиваться, что не получилось. Три тренировки в неделю, которые ты правда делаешь, работают лучше, чем пять, которые постоянно срываются.'),
  ('why_walking_helps', 'Почему полезно просто ходить', 'Ходьба — один из самых недооценённых инструментов в любой программе про тело и привычки. У неё нет побочных эффектов в виде выгорания или перетренированности, она почти не требует восстановления, её можно делать каждый день, и она не зависит от настроения или мотивации так сильно, как силовая тренировка. Дополнительное движение в течение дня — прогулка, лестница вместо лифта, короткая прогулка после ужина — суммарно часто влияет на самочувствие и результат не меньше, чем сами тренировки, особенно если раньше в жизни движения было мало. Ходьба также хорошо помогает справляться со стрессом и тягой к сладкому, потому что переключает состояние нервной системы. Не нужно превращать её в ещё один пункт для перфекционизма с точным количеством шагов — достаточно ориентира «сегодня я подвигалась немного больше, чем вчера». Это тот вид активности, который проще всего встроить в обычный день, не перестраивая весь график.'),
  ('motivation_fades', 'Почему мотивация заканчивается', 'Мотивация — это эмоция, а эмоции по своей природе нестабильны: они то есть, то их нет, независимо от того, насколько правильно ты всё делаешь. Ждать, что мотивация будет одинаково сильной все 56 дней, — то же самое, что ждать одинаковой погоды каждый день. Программы, которые полагаются только на мотивацию и вдохновляющие лозунги, обычно работают ровно до первого дня, когда вдохновения не случилось. Более надёжная стратегия — опираться не на мотивацию, а на систему: маленькие конкретные задачи на сегодня, чек-лист, который не требует решений «хочу ли я сейчас», и привычку, которая выполняется даже в низкоэнергетичные дни в упрощённом виде. Именно поэтому в BODY RESET каждый день — это не абстрактный призыв «будь лучше», а одно конкретное действие. Когда мотивации нет, не нужно ждать, пока она появится — можно просто выполнить сегодняшнюю маленькую задачу. Часто именно действие возвращает ощущение движения вперёд, а не наоборот.'),
  ('plateau', 'Что делать при плато', 'Плато — период, когда вес и объёмы почти не меняются несколько недель подряд, — совершенно нормальная часть процесса, а не сигнал, что нужно резко всё менять. Тело адаптируется к новому уровню активности и питания, и на это требуется время. Первая и самая частая ошибка на плато — резко урезать питание или добавить ещё больше тренировок: чаще всего это ведёт к усталости и откату, а не к прогрессу. Прежде чем что-то менять, стоит честно спросить себя: действительно ли программа выполняется в том виде, как задумано — тренировки, движение, более-менее сбалансированные приёмы пищи, сон, — или незаметно накопилось несколько послаблений. Если да — часто достаточно просто продолжать ещё 2–3 недели, ничего не меняя. Если система выполняется стабильно, а плато затянулось надолго, это повод не для паники, а для спокойного пересмотра деталей вместе с AI Coach или специалистом, а не для радикальных мер.'),
  ('one_bad_day', 'Почему один плохой день ничего не решает', 'Результат за 56 дней определяется не тем, насколько идеальным был каждый отдельный день, а тем, какой была общая картина за все восемь недель. Если представить прогресс как линию, один провальный день — это всего лишь одна точка из пятидесяти шести, и она почти не влияет на общий наклон линии. Проблема возникает не из-за самого плохого дня, а из-за истории, которую мы себе рассказываем после него: «я всё испортила, значит, можно бросать». Именно эта мысль, а не сам день, останавливает прогресс. Гораздо более полезный взгляд: плохой день — это просто плохой день, после которого программа продолжается как обычно, без специального «искупления» или, наоборот, полного отказа от системы. Не нужно ни наказывать себя дополнительной тренировкой или голоданием, ни решать, что раз день не удался, то и неделя, и вся программа тоже. Закрой сегодняшний день и открой завтрашний — это всё, что требуется.'),
  ('eating_out', 'Как питаться в ресторане', 'Поход в ресторан не обязан выбивать из программы — систему «сбалансированная тарелка» легко перенести и на меню кафе. Ориентируйся на тот же принцип: блюдо с понятным источником белка (мясо, рыба, птица, тофу, бобовые), что-то из овощей или салата, и один источник углеводов — вместо того чтобы пытаться высчитать точный состав блюда. Если в меню сложно найти такой вариант, можно попросить заменить гарнир на салат или овощи, попросить соус отдельно, чтобы регулировать количество самой, — это нормальная и частая практика, официанты к ней привыкли. Не нужно приходить в ресторан заранее голодной «чтобы сэкономить» — это обычно приводит к перееданию за столом. Один поход в ресторан не требует специальной подготовки или последующей компенсации: это просто один приём пищи среди примерно 150 приёмов пищи за 56 дней. Разреши себе получить удовольствие от еды и от компании — это тоже часть здоровых отношений с едой.'),
  ('vacation', 'Как вести себя в отпуске', 'Отпуск — не режим «программа приостановлена», но и не повод превращать каждый день в жёсткий контроль. Более здоровый подход — перенести с собой не меню, а несколько простых принципов: стараться, чтобы в большинстве приёмов пищи был белок и что-то из овощей, пить достаточно воды, двигаться в своём удовольствии — прогулки, плавание, экскурсии тоже считаются активностью, необязательно искать спортзал. Если структурированных тренировок в отпуске не получается — это нормально, программа не пострадает от одной-двух недель без силовых тренировок, особенно если сохраняется общая активность. Не нужно ставить себе цель «не набрать ни грамма в отпуске» — это источник тревожности, а не пользы. После возвращения не нужен ни разгрузочный день, ни жёсткий рывок «наверстать» — просто открой сегодняшний день программы и продолжай как обычно. Отпуск — это часть жизни, а система BODY RESET существует для того, чтобы вписываться в жизнь, а не отменять её.'),
  ('after_holidays', 'Как вернуться после праздников', 'После череды праздничных застолий самое частое желание — устроить себе несколько дней жёсткого ограничения «чтобы компенсировать». Это как раз тот шаг, которого стоит избегать: резкое урезание питания после нескольких сытных дней обычно приводит к сильному голоду, срыву и ощущению неудачи, а не к быстрому результату. Гораздо более рабочий путь — просто вернуться к обычной системе программы: сбалансированные приёмы пищи, обычные тренировки, обычная вода и сон, без специальных «очищений» или голодных дней. Изменения на весах после праздников почти всегда включают воду и объём съеденной пищи, а не жир, и они довольно быстро уходят сами при возврате к обычному режиму — часто в течение недели. Не нужно взвешиваться каждый час и тревожиться из-за цифры сразу после праздников — дай телу пару дней на обычную жизнь. Открой сегодняшний день программы, выполни его — и этого достаточно, чтобы снова быть в системе.'),
  ('sleep_matters', 'При чём тут сон', 'Сон часто остаётся самым недооценённым элементом программ про тело, хотя влияет почти на всё остальное: недосып усиливает тягу к сладкому и простым углеводам, снижает энергию для тренировок, ухудшает восстановление мышц и делает эмоции менее стабильными — а значит, сложнее придерживаться плана в принципе. Не обязательно гнаться за «идеальными» 8 часами каждую ночь — для большинства людей более реалистичная и полезная цель — стабильное время отхода ко сну и подъёма, даже если сама продолжительность варьируется. Если чувствуешь, что тянет на сладкое сильнее обычного, или тренировка сегодня даётся особенно тяжело, — прежде чем винить недостаток силы воли, стоит честно спросить себя, сколько ты спала в последние пару дней. В ежедневном чек-листе поэтому есть отдельный пункт про сон — не потому что нужно спать «идеально», а потому что честное отслеживание помогает заметить связь между сном и тем, как проходит день.'),
  ('evening_hunger', 'Как справляться с вечерним голодом', 'Сильный голод по вечерам почти никогда не возникает «просто так» — чаще всего это следствие того, что в течение дня приёмы пищи были слишком редкими, слишком маленькими или в них не хватало белка и клетчатки, которые дают длительное чувство сытости. Если вечером тебя тянет доедать всё подряд, первое, на что стоит посмотреть, — это завтрак и обед: были ли они достаточно плотными, не пропускался ли перекус. Отдельная частая причина — эмоциональная, а не физическая: усталость после дня, стресс или просто привычка «наконец расслабиться с едой перед сном». Обе причины не решаются запретом на вечернюю еду — это только увеличивает шанс переедания. Более рабочий путь — сделать основные приёмы пищи в течение дня достаточно сытными, разрешить себе сбалансированный вечерний приём пищи или перекус без чувства вины, и отдельно поискать не связанный с едой способ снять напряжение вечером — прогулку, душ, разговор, что угодно, что действительно помогает.'),
  ('comparison', 'Про сравнение себя с другими', 'Легко начать сравнивать свой прогресс с прогрессом других участниц — по фото, по цифрам, по скорости изменений — и от этого сравнения обычно становится хуже, а не лучше, потому что у каждого тела разная стартовая точка, гормональный фон, история отношений с едой и телом, доступное время на тренировки и сон. Программа рассчитана на 56 дней одинаково для всех, но скорость и характер изменений внутри неё у всех будут разными — это не показатель того, что ты стараешься меньше или делаешь что-то неправильно. Единственное сравнение, которое реально полезно, — это сравнение себя сегодняшней с собой в День 1: как изменилась энергия, привычки, отношения с едой, уверенность в теле, а не только цифра на весах. Раздел «Прогресс» в приложении поэтому строится именно на твоих собственных данных, а не на рейтинге или сравнении с другими участницами.'),
  ('realistic_expectations', 'Как ставить реалистичные ожидания', 'Один из самых частых источников разочарования в любой программе — ожидания, которые не совпадают с тем, как на самом деле происходят изменения в теле. Реальный процесс редко бывает линейным: недели заметного прогресса чередуются с неделями, когда как будто ничего не происходит, а иногда цифры на весах даже немного растут при том, что объём уменьшается. BODY RESET сознательно не обещает конкретное количество килограммов или точные сроки — потому что честно предсказать это невозможно, а обещания такого рода обычно приводят только к разочарованию и ощущению, что программа «не сработала», даже когда прогресс на самом деле есть. Более реалистичный и полезный ориентир — не конкретное число, а направление: тренировки становятся привычнее, питание — более сбалансированным без чувства лишения, энергии и сна — больше, отношения с едой — спокойнее. Если через 56 дней это направление есть, программа выполнила свою задачу, даже если финальная цифра на весах не такая, как представлялось в День 1.'),
  ('water_role', 'Зачем нужна вода', 'Вода — простой, но часто упускаемый элемент программы. Достаточное количество воды в течение дня помогает лучше отличать голод от жажды (иногда лёгкое обезвоживание ощущается похоже на голод и приводит к лишнему перекусу), поддерживает энергию и самочувствие во время тренировок, помогает пищеварению и может немного снижать тягу к перекусам между основными приёмами пищи. Не нужно высчитывать точное количество миллилитров или заставлять себя пить через силу — достаточно простого ориентира: стакан воды после пробуждения, вода в течение дня по ощущению жажды, и особенно перед приёмом пищи, если непонятно, реальный это голод или нет. В жаркую погоду или после активной тренировки потребность в воде естественно выше. Пункт «вода» в ежедневном чек-листе — это не про строгий норматив, а про то, чтобы в принципе держать эту привычку в поле внимания, а не забывать про воду весь день и вспоминать только вечером.'),
  ('weekly_review_meaning', 'Зачем нужны еженедельные итоги', 'Раз в 7 дней программа просит остановиться и подвести итоги недели — не для того, чтобы выставить себе оценку, а чтобы увидеть картину шире, чем один день. В ежедневном режиме легко зациклиться на том, что сегодня не получилось, и не заметить, что за неделю в целом было 5 из 7 тренировок, стабильный сон и заметно более спокойное отношение к еде. Еженедельный обзор — это возможность честно отметить: что получилось особенно хорошо, что было сложнее всего, и стоит ли что-то скорректировать в следующей неделе — например, снизить количество тренировок, если их постоянно не хватает сил выполнить, или, наоборот, добавить активности, если стало легко. Это не экзамен с проходным баллом, а рабочий инструмент — как короткая встреча с самой собой раз в неделю. Отвечай на вопросы обзора честно, а не так, как «должно быть правильно» — только тогда от него есть реальная польза для следующей недели.');
insert into daily_tasks (day_number, task_type, title, description) values
  (1, 'habit', 'Не пытайся изменить всю жизнь за один день. Твоя задача — просто начать.', null),
  (2, 'habit', 'Добавь овощи минимум к двум основным приёмам пищи.', null),
  (3, 'habit', 'Сделай тренировку и не оценивай её по калориям.', null),
  (4, 'habit', 'Сегодня выпей воду перед первым приёмом пищи.', null),
  (5, 'habit', '10–20 минут дополнительной ходьбы.', null),
  (6, 'habit', 'Запиши три вещи, которые сегодня получилось сделать.', null),
  (7, 'habit', 'Подведи итоги первой недели.', null),
  (8, 'habit', 'Выбери одно время дня для перекуса — и придерживайся его сегодня.', null),
  (9, 'habit', 'Приготовь один приём пищи заранее, чтобы не решать в последний момент, что есть.', null),
  (10, 'habit', 'Сделай тренировку в то же время, что и в прошлый раз — так рождается привычка.', null),
  (11, 'habit', 'Ляг спать сегодня на 30 минут раньше обычного.', null),
  (12, 'habit', 'Заранее собери список продуктов на завтра.', null),
  (13, 'habit', 'Отметь время дня, когда тебе сложнее всего — и подготовь для него простой план.', null),
  (14, 'habit', 'Подведи итоги второй недели.', null),
  (15, 'habit', 'Сделай тренировку, даже если нет настроения — сократи вдвое, но не пропускай.', null),
  (16, 'habit', 'Замени один сладкий перекус на белковый или фруктовый.', null),
  (17, 'habit', 'Пройди сегодня немного больше шагов, чем вчера.', null),
  (18, 'habit', 'Приготовь ужин без сложного рецепта — простое блюдо тоже считается.', null),
  (19, 'habit', 'Отметь один момент, когда было сложно, и как ты с этим справилась.', null),
  (20, 'habit', 'Сделай растяжку 5–10 минут вместо пропущенной тренировки.', null),
  (21, 'habit', 'Подведи итоги третьей недели.', null),
  (22, 'habit', 'Добавь один дополнительный подход в тренировке, если чувствуешь, что можешь.', null),
  (23, 'habit', 'Сделай приседания медленнее и осознаннее — обрати внимание на технику.', null),
  (24, 'habit', 'Добавь источник белка к завтраку, если обычно его там немного.', null),
  (25, 'habit', 'Сделай короткую прогулку после ужина.', null),
  (26, 'habit', 'Запиши, как изменилось самочувствие за месяц — не вес, а именно ощущения.', null),
  (27, 'habit', 'Сделай сегодня чуть более сложный вариант тренировки, если это по силам.', null),
  (28, 'habit', 'Подведи итоги четвёртой недели — отметь, что стало привычнее.', null),
  (29, 'habit', 'Если вчера был трудный день — не начинай сегодня с наказания, просто продолжи план.', null),
  (30, 'habit', 'Замени перекус «на бегу» на перекус за столом, без спешки.', null),
  (31, 'habit', 'Сделай тренировку в непривычное время дня, если обычный слот сегодня не подходит.', null),
